import{_ as e,o as s,c as n,a6 as o}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"CDN / 边缘缓存 · SSR 的 HTML 怎么被缓存","description":"CDN 缓存是保护 SSR 源站最关键的一层：第一个请求触发一次渲染，之后成千上万个请求全从边缘秒回，源站再也碰不到。这一章讲清缓存键、命中状态、源站屏蔽，以及最凶险的「缓存击穿」。","frontmatter":{"title":"CDN / 边缘缓存 · SSR 的 HTML 怎么被缓存","description":"CDN 缓存是保护 SSR 源站最关键的一层：第一个请求触发一次渲染，之后成千上万个请求全从边缘秒回，源站再也碰不到。这一章讲清缓存键、命中状态、源站屏蔽，以及最凶险的「缓存击穿」。","source":"https://daiw.org/manual/ssr/cdn-caching"},"headers":[],"relativePath":"manual/computer-programming/ssr/cdn-caching.md","filePath":"manual/computer-programming/ssr/cdn-caching.md"}'),r={name:"manual/computer-programming/ssr/cdn-caching.md"};function t(i,a,l,c,d,p){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="cdn-边缘缓存-·-ssr-的-html-怎么被缓存" tabindex="-1">CDN / 边缘缓存 · SSR 的 HTML 怎么被缓存 <a class="header-anchor" href="#cdn-边缘缓存-·-ssr-的-html-怎么被缓存" aria-label="Permalink to &quot;CDN / 边缘缓存 · SSR 的 HTML 怎么被缓存&quot;">​</a></h1><p>CDN 缓存是保护 SSR 源站最关键的一层：第一个请求触发一次渲染，之后成千上万个请求全从边缘秒回，源站再也碰不到。这一章讲清缓存键、命中状态、源站屏蔽，以及最凶险的「缓存击穿」。</p><p>在<a href="/Front2Full/manual/computer-programming/ssr/why-cache">缓存分层</a> 里，CDN 是<strong>最关键的一层</strong>——因为它是<strong>唯一能让请求「根本到不了你服务器」的缓存</strong>。浏览器缓存只保护单个用户，CDN 缓存保护的是<strong>你的源站</strong>。对 SSR 来说，这层几乎决定生死。</p><h2 id="一次渲染-服务所有人" tabindex="-1">一次渲染，服务所有人 <a class="header-anchor" href="#一次渲染-服务所有人" aria-label="Permalink to &quot;一次渲染，服务所有人&quot;">​</a></h2><p>CDN（内容分发网络）是一张遍布全球的边缘节点网。它缓存 SSR 页面的逻辑，就是<a href="/Front2Full/manual/computer-programming/ssr/http-caching">上一章</a> <code>Cache-Control</code> 的直接应用：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[&quot;第一个用户请求 /article/42&quot;] --&gt; B[&quot;CDN:缓存里没有(MISS)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[&quot;回源:服务器渲染一次 SSR&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[&quot;CDN 把结果存下(按 s-maxage)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E[&quot;返回给这个用户&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  F[&quot;之后成千上万个请求&quot;] --&gt; G[&quot;CDN:命中(HIT)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  G --&gt; H[&quot;从边缘直接秒回&lt;br/&gt;源站毫不知情&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>关键就在最后两步：<strong>只有第一个（缓存未命中的）请求真的触发了渲染；在 <code>s-maxage</code> 有效期内，后续所有请求都由 CDN 从边缘直接返回，你的源站一次都没被碰到。</strong> 这叫<strong>源站屏蔽(origin shielding)</strong>。一个 <code>s-maxage=60</code> 的热门页，哪怕每秒一万次访问，源站每 60 秒也只渲染<strong>一次</strong>——扛量能力天差地别。</p><h2 id="缓存键-cdn-怎么判断「是不是同一个」" tabindex="-1">缓存键：CDN 怎么判断「是不是同一个」 <a class="header-anchor" href="#缓存键-cdn-怎么判断「是不是同一个」" aria-label="Permalink to &quot;缓存键：CDN 怎么判断「是不是同一个」&quot;">​</a></h2><p>CDN 用<strong>缓存键(cache key)</strong> 来判断一个请求能不能命中已有缓存。默认的键就是 <strong>URL</strong>（方法 + 主机 + 路径 + 查询串），再加上响应里 <a href="/Front2Full/manual/computer-programming/ssr/http-caching"><code>Vary</code></a> 声明的那些请求头。</p><p>这带来两个实战要点：</p><ul><li><strong>查询参数会切分缓存</strong>：<code>/list?page=1</code> 和 <code>/list?page=2</code> 是两个键，各存各的。但要小心<strong>无意义的参数</strong>（如营销追踪的 <code>?utm_source=...</code>）——它们会让同一个页面产生无数缓存键、命中率暴跌。通常要配置 CDN <strong>忽略</strong>这类参数。</li><li><strong><code>Vary</code> 会成倍切分</strong>：上一章说过，<code>Vary: Cookie</code> 会按用户切分，基本等于关缓存。</li></ul><h2 id="看懂命中状态" tabindex="-1">看懂命中状态 <a class="header-anchor" href="#看懂命中状态" aria-label="Permalink to &quot;看懂命中状态&quot;">​</a></h2><p>CDN 通常会在响应头里告诉你这次是命中还是未命中，排查缓存问题时第一个要看它：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CF-Cache-Status: HIT       # Cloudflare:命中</span></span>
<span class="line"><span>X-Cache: HIT from ...      # 通用:命中</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>常见状态：<strong><code>HIT</code></strong>（命中，边缘直接给）、<strong><code>MISS</code></strong>（未命中，回源了）、<strong><code>EXPIRED</code></strong>（过期后回源）、<strong><code>STALE</code></strong>（给了旧的，见<a href="/Front2Full/manual/computer-programming/ssr/swr">下一章</a>）、<strong><code>BYPASS</code></strong>（被判定不可缓存，直接回源）。<strong>上线后第一件事，就是确认你想缓存的页面真的是 <code>HIT</code></strong>——很多「缓存没生效」的问题，一看状态头就水落石出。</p><h2 id="什么会让-cdn-«不缓存»" tabindex="-1">什么会让 CDN «不缓存» <a class="header-anchor" href="#什么会让-cdn-«不缓存»" aria-label="Permalink to &quot;什么会让 CDN «不缓存»&quot;">​</a></h2><p>一个常见的困惑是「我设了 <code>s-maxage</code>，怎么还是 <code>BYPASS</code>？」。CDN 出于安全，默认会<strong>跳过缓存</strong>若干情况：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>响应里带 <code>Set-Cookie</code>，多数 CDN 会拒绝缓存这个响应</strong>——因为 Cookie 通常是给某个用户设的会话，缓存下来发给别人就危险了。这是个高频坑：你的 SSR 框架 / 中间件可能<strong>不知不觉给每个响应都带上了 <code>Set-Cookie</code></strong>（比如某个分析、会话中间件），结果整站缓存全部失效、<code>BYPASS</code> 满天飞。<strong>排查缓存不生效，第二件事就是看响应有没有多余的 <code>Set-Cookie</code>。</strong> 其它默认不缓存的：非 <code>GET</code> 请求、<code>Cache-Control: private/no-store</code>、带 <code>Authorization</code> 头的请求。</p></div><h2 id="最凶险的坑-缓存击穿" tabindex="-1">最凶险的坑：缓存击穿 <a class="header-anchor" href="#最凶险的坑-缓存击穿" aria-label="Permalink to &quot;最凶险的坑：缓存击穿&quot;">​</a></h2><p>CDN 缓存有个经典的失效瞬间，叫<strong>缓存击穿 / 惊群(cache stampede / thundering herd)</strong>:</p><blockquote><p>一个超热门页面的缓存<strong>刚好过期</strong>的那一刻，成百上千个并发请求<strong>同时</strong>发现「缓存没了」，于是<strong>同时回源</strong>——源站在一瞬间被灌入海量渲染请求，可能直接被打挂。</p></blockquote><p>明明有缓存，却在过期的刹那被瞬间流量击穿。缓解办法有几个，都值得知道：</p><ul><li><strong>请求合并(request coalescing / dedup)</strong>：好的 CDN 在缓存未命中时，会把「同一个键的并发回源请求」<strong>合并成一个</strong>发给源站，其余的等这一个的结果。多数主流 CDN 默认就做这个——但要确认你用的开了。</li><li><strong><code>stale-while-revalidate</code></strong>：过期后<strong>先拿旧的顶着</strong>、后台再更新，压根不产生「同时回源」的尖峰。这个解法相当优雅，正是<a href="/Front2Full/manual/computer-programming/ssr/swr">下一章</a>的主题。</li><li><strong>错开过期时间</strong>：给 TTL 加一点随机抖动，别让大批页面在同一秒集体过期。</li></ul><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>CDN 缓存是保护 SSR 源站的命门：一次渲染经边缘服务所有人，源站屏蔽让扛量能力质变。用好它要懂<strong>缓存键</strong>（别被查询参数 / <code>Vary</code> 切碎）、会看<strong>命中状态</strong>、警惕 <strong><code>Set-Cookie</code> 导致的 <code>BYPASS</code></strong>，以及防住<strong>缓存击穿</strong>。</p><p>刚才反复提到的那个「过期后先给旧的、后台再更新」——它太重要，值得单独讲透。它既是防击穿的利器，也是理解 ISR 的钥匙，更是「又快又不太旧」这个看似矛盾目标的答案。👉 <a href="/Front2Full/manual/computer-programming/ssr/swr">stale-while-revalidate：又快，又不太旧</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Cloudflare.「How CDN caching works / Cache keys.」<a href="https://developers.cloudflare.com/cache/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/cache/</a> —— CDN 缓存、缓存键、命中状态。</li><li>[2] MDN.「HTTP caching — shared caches.」<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching</a> —— 共享缓存与回源。</li><li>[3] Nginx.「Mitigating thundering herd / proxy_cache_lock.」<a href="https://www.nginx.com/blog/" target="_blank" rel="noreferrer">https://www.nginx.com/blog/</a> —— 缓存击穿与请求合并。</li></ul>`,28)])])}const u=e(r,[["render",t]]);export{h as __pageData,u as default};
